#!/usr/bin/env python3
"""All-region 6/7-node transfer MMS, guard semantics, and convergence plots."""
import argparse,hashlib,json,math,os
from pathlib import Path
p=argparse.ArgumentParser();p.add_argument('directory',type=Path);a=p.parse_args();d=a.directory;rows=[json.loads(f.read_text()) for f in sorted(d.glob('mms*.stdout')) if f.stat().st_size];manifest=json.loads((d/'manifest.json').read_text());out=dict(scope='Standalone physical-normal Hermite boundary-jet MMS; frozen pole and Minkowski checks separate; no evolution adoption',prototype_not_adopted=True,physics_gate_tested=False,results=rows,all_tests_exit_zero=all(x['exit_code']==0 for x in manifest['runs'].values()),all_constants_exact=all(x['constant_max']==0 for x in rows),maximum_normal_jet_change=max(x['original_pure_normal_jet_difference_max'] for x in rows),maximum_angular_value_weight_l1=max(x['value_weight_l1_max'] for x in rows),maximum_factor_condition_indicator=max(x['angular_radial_factor_condition_indicator'] for x in rows),maximum_polynomial_reproduction=max(x['polynomial_reproduction_max'] for x in rows),all_cells_under50000=all(x['cells']<=50000 for x in rows),zero_trace_tangent_gradient_max=max(x['zero_trace_tangent_gradient_max'] for x in rows),zero_trace_intrinsic_hessian_max=max(x['zero_trace_intrinsic_hessian_max'] for x in rows),quadratic_trace_normal_max=max(x['quadratic_trace_normal_max'] for x in rows),quadratic_trace_mixed_max=max(x['quadratic_trace_mixed_max'] for x in rows),condition_semantics='Product of angular QR-R infinity condition and scaled radial Vandermonde infinity condition; a field-independent guard indicator, not a measured full jet-design condition number. Value L1 guard applies to angular interpolation; original dimensionful radial differentiation contract is retained.',polynomial_semantics='Angular21 monomial value reproduction and independent radial normal derivative moment reproduction, degree5/6 for6/7nodes. Cartesian first/second jets independently compared with analytic differentiation; no claim of exact finite-difference derivatives of every fifth-degree polynomial.',observed_orders=[],retained_counterexamples=['CoarseN6 angular Hessian errors can exceed original owner interpolation. They remain underresolved controls.','Interior-dependent endpoint CartesianMLS violates zero trace tangential derivative preservation; rejected before any evolution adoption.'])
for layers in [1,2,7]:
 for radial in [6,7]:
  selected=sorted((x for x in rows if x['layers']==layers and x['subdivisions']==1 and x['radial_nodes']==radial),key=lambda x:x['n'])
  for x,y in zip(selected,selected[1:]):
   pair=dict(layers=layers,radial_nodes=radial,n_from=x['n'],n_to=y['n'],orders={})
   for region in ['all_surface','edge_band','corner_band','exact_patch_seams_and_corners','owner_all_surface','owner_exact_seams','analytic_pullback_all_surface','analytic_pullback_exact_seams']:
    pair['orders'][region]={k:math.log(x[region][k]/y[region][k])/math.log(y['n']/x['n']) for k in ['first_max','second_max','normal_tangent_hessian_max'] if x[region][k]>0 and y[region][k]>0}
   out['observed_orders'].append(pair)
