os.environ.setdefault('XDG_CACHE_HOME',str(Path.cwd()/'tmp/fontcache-boundary-transfer'));os.environ.setdefault('MPLCONFIGDIR',str(Path.cwd()/'tmp/matplotlib-boundary-transfer'));import matplotlib;matplotlib.use('Agg');import matplotlib.pyplot as plt
fig,axes=plt.subplots(3,3,figsize=(12,10));columns=[('all_surface','second_max','All nodes: Hessian max'),('exact_patch_seams_and_corners','second_max','Exact seams/corners: Hessian max'),('exact_patch_seams_and_corners','normal_tangent_hessian_max','Exact seams/corners: mixed max')]
for i,layers in enumerate([1,2,7]):
 for j,(region,metric,title) in enumerate(columns):
  ax=axes[i,j]
  for radial,style in [(6,'o-'),(7,'s--')]:
   selected=sorted((x for x in rows if x['layers']==layers and x['subdivisions']==1 and x['radial_nodes']==radial),key=lambda x:x['n']);ax.loglog([x['n'] for x in selected],[x[region][metric] for x in selected],style,label=f'new, {radial} radial nodes')
  selected=sorted((x for x in rows if x['layers']==layers and x['subdivisions']==1 and x['radial_nodes']==6),key=lambda x:x['n']);old='owner_all_surface' if region=='all_surface' else 'owner_exact_seams';oracle='analytic_pullback_all_surface' if region=='all_surface' else 'analytic_pullback_exact_seams';ax.loglog([x['n'] for x in selected],[x[old][metric] for x in selected],'x:',color='.5',label='owner face');ax.loglog([x['n'] for x in selected],[x[oracle][metric] for x in selected],'+-.',color='black',label='exact-query FD control');ax.text(.5,1.025,f'{layers} shell(s): {title}',transform=ax.transAxes,ha='center',va='bottom',fontsize=9,color='black',clip_on=False);ax.grid(True,which='both',alpha=.25);ax.set_xticks([x['n'] for x in selected]);ax.get_xaxis().set_major_formatter(matplotlib.ticker.ScalarFormatter());ax.get_xaxis().set_minor_formatter(matplotlib.ticker.NullFormatter());ax.set_xlabel('N per block axis');ax.set_ylabel('Maximum absolute derivative error')
axes[0,0].legend(fontsize=7);fig.suptitle('Physical-normal Hermite atlas: independent AD MMS; all nodes retained; no evolution claim',fontsize=12);fig.tight_layout();fig.savefig(d/'convergence.png',dpi=160);fig.savefig(d/'convergence.pdf');plt.close(fig)
